INSERT INTO lessons (level_id,lesson_key,sort_order,title,title_translation,description,primary_outcome_key,estimated_duration_sec,source_hash,status,metadata)
VALUES (@level_id,'EN-A1-L-0116',116,'The door is open','در باز است','با open باز بودن یک در یا پنجره را توصیف کن.','EN-A1-OUTCOME-0116',420,'1946c47ce598418f9b20504593ad79baac9535c1064814f819dfec97d6d7874b','validated','{"outcomeFa":"open را به معنی «باز/نبسته» در دو جمله کوتاه به کار ببری.","scenarioFa":"سارا و روبی بعد از پیاده‌روی وارد کتابخانه می‌شوند و درباره در و پنجره باز حرف می‌زنند.","prerequisiteOutcomeKeys":["EN-A1-OUTCOME-0115"],"curriculum":{"startingKnowledge":"early_a1_spoken_core_and_recent_review","targetConstructions":[{"key":"EN-CONSTR-0116-OPEN","form":"The door is open","meaningFa":"توصیف چیزی که بسته نیست"}],"supportLanguage":[{"form":"Can we go in?","meaningFa":"می‌توانیم داخل برویم؟"},{"form":"And the window?","meaningFa":"پنجره چطور؟"}],"assessmentBoundary":"Only the bounded A1 adjective sense of open meaning not shut or closed is assessed.","transferPlan":{"mode":"same_lesson","intent":"Reuse the same adjective sense with a second familiar object."},"story":{"arcKey":"EN-A1-WALKING-GROUP","sceneKey":"EN-A1-FACTORY-SCENE-0116","learnerRoleKey":"ruby","participants":["sara","ruby"],"introducedCharacterKeys":[],"relationshipState":"already_known","dependsOnLessonKeys":["EN-A1-L-0111"],"continuesLessonKey":"EN-A1-L-0111","settingFa":"ورودی کتابخانه بعد از پیاده‌روی","storyBeatFa":"سارا درباره ورود و پنجره می‌پرسد و روبی با open باز بودن آن‌ها را توصیف می‌کند."},"reviewLinks":[{"lessonKey":"EN-A1-L-0111","activityKeys":["A02"],"learningDemand":"retrieval","note":"Returning walking-group arc is spaced by 5 Lessons and the played role changes from Sara to Ruby."}],"languageReference":{"specKey":"en-fa-A1-LESSON-SPEC-0116","specHash":"9b1ea7ef9fc2b403d6e7ae915877682749bd1ef15bc6cda4182cbcfd4919f3cd","grammarTargetKeys":[],"reviewLexicalLemmas":[],"usageFallbacks":[{"query":"door is open","rationale":"Exact deterministic target-collocation window from The door is open for the bounded adjective sense meaning not closed."},{"query":"window is open too","rationale":"Exact deterministic changed-context window preserving the same adjective sense."}],"noNewGrammarReason":"Lexical-focus Lesson; the committed reference sense is adjectival, so no imperative verb sense is claimed."},"pedagogyVersion":2},"pilot":false,"audioRequired":true,"humanEnglishAuditRequired":true,"dialogueRuntime":"guided_exchange","qualityStage":"model_reviewed_for_testing"}')
ON DUPLICATE KEY UPDATE level_id=VALUES(level_id),sort_order=VALUES(sort_order),title=VALUES(title),title_translation=VALUES(title_translation),description=VALUES(description),primary_outcome_key=VALUES(primary_outcome_key),estimated_duration_sec=VALUES(estimated_duration_sec),source_hash=VALUES(source_hash),status=VALUES(status),metadata=VALUES(metadata);
SET @lesson_id=(SELECT id FROM lessons WHERE level_id=@level_id AND lesson_key='EN-A1-L-0116' LIMIT 1);
DELETE FROM lesson_lexical_items WHERE lesson_id=@lesson_id;

-- Keep existing activities IDs; remove only keys absent from this Lesson source.
DELETE FROM activities WHERE lesson_id=@lesson_id AND activity_key NOT IN ('A01','A02','A03','A04','A05','A06');
SET @child_order_offset=(SELECT GREATEST(COALESCE(MAX(sort_order),0),6) FROM activities WHERE lesson_id=@lesson_id);
UPDATE activities SET sort_order=sort_order+@child_order_offset WHERE lesson_id=@lesson_id ORDER BY sort_order DESC;

-- Keep existing lesson_turns IDs; remove only keys absent from this Lesson source.
DELETE FROM lesson_turns WHERE lesson_id=@lesson_id AND turn_key NOT IN ('T01','T02','T03','T04');
SET @child_order_offset=(SELECT GREATEST(COALESCE(MAX(sort_order),0),4) FROM lesson_turns WHERE lesson_id=@lesson_id);
UPDATE lesson_turns SET sort_order=sort_order+@child_order_offset WHERE lesson_id=@lesson_id ORDER BY sort_order DESC;

